 class Peer implements AutoCloseable {
  final String tag;final Socket socket=new Socket();final Protocol.CipherState incoming,outgoing;final List<byte[]> received=new ArrayList<>();Map<Long,Item> inventory=new LinkedHashMap<>();
  Peer(String tag,String host,int port)throws Exception{this.tag=tag;socket.connect(new InetSocketAddress(host,port),3000);socket.setSoTimeout(12000);socket.setTcpNoDelay(true);byte[] key=Protocol.readFrame(socket.getInputStream(),8192);require(key!=null&&key.length==5&&(key[0]&255)==Protocol.S_KEY,"actual S_KEY");var r=new Protocol.Reader(key);r.c();int seed=(int)r.d();incoming=new Protocol.CipherState(seed);outgoing=new Protocol.CipherState(seed);wire.add(Map.of("peer",tag,"direction","S","payload_hex",HexFormat.of().formatHex(key),"unencrypted_key",true));}
  void send(byte[] p)throws Exception{wire.add(Map.of("peer",tag,"direction","C","opcode",p[0]&255,"payload_hex",(p[0]&255)==Protocol.C_LOGIN?"fixture credentials redacted":HexFormat.of().formatHex(p)));Protocol.writeFrame(socket.getOutputStream(),outgoing.encrypt(p));}
  byte[] receive()throws Exception{byte[] f=Protocol.readFrame(socket.getInputStream(),65535);if(f==null)return null;byte[] p=incoming.decrypt(f);received.add(p);wire.add(Map.of("peer",tag,"direction","S","payload_hex",HexFormat.of().formatHex(p)));update(p);return p;}
  byte[] await(int op)throws Exception{for(int i=0;i<1000;i++){byte[] p=receive();require(p!=null,"peer closed awaiting "+op+" stage="+stage);if((p[0]&255)==op)return p;}throw new AssertionError("frame bound opcode="+op);}
  void auth(String account)throws Exception{send(new Protocol.Writer().c(Protocol.C_VERSION).h(Protocol.VERSION_MAGIC).d(Protocol.VERSION_PRODUCT).c(2).h(Protocol.VERSION_BUILD).bytes());byte[] p=await(Protocol.S_VERSION_CHECK);require(p.length>=2&&p[1]==0,"version accepted");send(new Protocol.Writer().c(Protocol.C_LOGIN).s(account).s(PASSWORD).d(0x0100007fL).bytes());}
  void update(byte[] p){int op=p[0]&255;if(op==Protocol.S_ADD_INVENTORY_BATCH||op==Protocol.S_ADD_INVENTORY){var r=new Protocol.Reader(p);r.c();int n=op==Protocol.S_ADD_INVENTORY_BATCH?r.c():1;if(op==Protocol.S_ADD_INVENTORY_BATCH)inventory.clear();for(int i=0;i<n;i++){long id=r.d();int use=r.c();r.c();int icon=r.h();r.c();long qty=r.d();r.c();String name=r.s();int len=r.c();for(int j=0;j<len;j++)r.c();inventory.put(id,new Item(id,icon,qty,use,name));}require(r.remaining()==0,"bounded actual inventory record");}else if(op==Protocol.S_REMOVE_INVENTORY){var r=new Protocol.Reader(p);r.c();inventory.remove(r.d());}}
  long item(int icon){return inventory.values().stream().filter(i->i.icon==icon).mapToLong(i->i.id).findFirst().orElseThrow(()->new AssertionError(tag+" missing actual server-issued inventory icon="+icon+" rows="+inventory));}
  void enterChannel()throws Exception{send(new Protocol.Writer().c(Protocol.C_LITO_ENTER_CHANNEL).c(0).bytes());byte[] p=await(Protocol.S_LITO_ENTER_CHANNEL_RESULT);require(p.length>=3&&p[1]==0&&p[2]==0,"channel accepted");await(Protocol.S_LITO_CHANNEL_INFO);}
  void use(long id)throws Exception{send(new Protocol.Writer().c(Protocol.C_USE_ITEM).d(id).s("").bytes());}
  void destroy(long id)throws Exception{send(new Protocol.Writer().c(Protocol.C_DESTROY_ITEM).d(id).bytes());}
  void quitAndLateDelete(long id)throws Exception{send(new Protocol.Writer().c(Protocol.C_QUIT).bytes());destroy(id);while(receive()!=null){}socket.close();}
  public void close()throws Exception{if(!socket.isClosed()){try{send(new Protocol.Writer().c(Protocol.C_QUIT).bytes());while(receive()!=null){}}finally{socket.close();}}}
 }
