 Peer loginReady(String tag,int port,String account)throws Exception{
  long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(20);int retries=0;
  while(true){Peer login=new Peer(tag+"-LOGIN-attempt"+retries,"127.0.0.1",port);try{login.auth(account);var check=new Protocol.Reader(login.await(Protocol.S_LOGIN_CHECK));check.c();int result=check.c();if(result==Protocol.LoginCheckResult.ACCEPTED.wireValue()){if(retries>0)checks.add(Map.of("case","actual login after prior disconnect cleanup","account",account,"ACCOUNT_IN_USE_retries",retries));return login;}require(result==Protocol.LoginCheckResult.ACCOUNT_IN_USE.wireValue(),"LOGIN credentials accepted or transient prior session cleanup result="+result);login.close();require(System.nanoTime()<deadline,"actual account release deadline");retries++;Thread.sleep(100);}catch(Throwable failure){login.close();throw failure;}}
 }
