   login.send(new Protocol.Writer().c(Protocol.C_LITO_LIN_CHARACTER_INFO).s(source).bytes());var route=new Protocol.Reader(login.await(Protocol.S_LITO_VS_SERVER_IP));route.c();require(route.c()==0&&route.d()==0x0200007fL&&route.h()==port&&route.remaining()==0,"source redirect exact");
